import ctypes

cdef class tt_state_t:
    cdef gsl_tt_state *state

    def __cinit__(self):
        self.state = gsl.gsl_tt_state_alloc()

    def __dealloc__(self):
        gsl.gsl_tt_state_free(self.state)

    def set_state(self, unsigned long seed):
        gsl.tt_set(seed, self.state)

    def get_random(self):
        return gsl.tt_get(self.state)

