gsl.tt_get.argtypes = [ctypes.POINTER(gsl_tt_state)]
gsl.tt_get.restype = ctypes.c_ulong
def generate_random_number(seed):
    state = tt_state_t()
    state.set_state(seed)
    return state.get_random()

