import ctypes

def load_gsl_libraries():
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    return ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def gsl_strerror(gsl_errno):
    gsl = load_gsl_libraries()
    gsl.gsl_strerror.restype = ctypes.c_char_p
    gsl.gsl_strerror.argtypes = [ctypes.c_int]
    return gsl.gsl_strerror(gsl_errno).decode('utf-8')

if __name__ == '__main__':
    assert gsl_strerror(1) == 'input domain error'
    assert gsl_strerror(2) == 'output range error'
    assert gsl_strerror(3) == 'underflow'
    assert gsl_strerror(4) == 'overflow'
    assert gsl_strerror(5) == 'divide by zero'
    print('All tests passed!')

