def integrate_function(func, a, b):
    assert isinstance(a, float) and isinstance(b, float), \"Interval bounds must be floats\"
    assert callable(func), \"Function to integrate must be callable\"

    gsl.gsl_integration_qk15.restype = ctypes.c_int
    gsl.gsl_integration_qk15.argtypes = [ctypes.POINTER(gsl_function), ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]

    result = ctypes.c_double(0)
    abserr = ctypes.c_double(0)
    resabs = ctypes.c_double(0)
    resasc = ctypes.c_double(0)

    gsl_func = gsl_function(func=ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(func), params=None)

    status = gsl.gsl_integration_qk15(ctypes.byref(gsl_func), a, b, ctypes.byref(result), ctypes.byref(abserr), ctypes.byref(resabs), ctypes.byref(resasc))

    if status != 0:
        raise Exception(\"Integration failed with status: {}\".format(status))

    return (result.value, abserr.value, resabs.value, resasc.value)

