import random

def allocate_rng(rng_name):
    try:
        cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        gsl_rng_type = ctypes.c_void_p
        gsl_rng = ctypes.c_void_p

        gsl.gsl_rng_alloc.argtypes = [ctypes.POINTER(gsl_rng_type)]
        gsl.gsl_rng_alloc.restype = ctypes.POINTER(gsl_rng)

        rng_types = {
            'mt19937': ctypes.c_void_p.in_dll(gsl, 'gsl_rng_mt19937')
        }

        if rng_name not in rng_types:
            raise ValueError("Unsupported random number generator type")

        rng_type_ptr = ctypes.byref(rng_types[rng_name])
        rng_ptr = gsl.gsl_rng_alloc(rng_type_ptr)

        if not rng_ptr:
            raise MemoryError("Failed to allocate random number generator")

        return rng_ptr

    except Exception as e:
        print(f"Error: {e}")
        return None

