import numpy as np

class gsl_matrix:
    def __init__(self, np_array):
        self.data = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
        self.size1 = np_array.shape[0]
        self.size2 = np_array.shape[1]
        self.tda = np_array.strides[1] // np_array.itemsize

class gsl_vector:
    def __init__(self, np_array):
        self.data = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
        self.size = np_array.size
        self.stride = np_array.strides[0] // np_array.itemsize

def numpy_to_gsl_matrix(np_array):
    return gsl_matrix(np_array)

def numpy_to_gsl_vector(np_array):
    return gsl_vector(np_array)

cdef hesstri_decomp(A, B, U, V, work):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
