def set_ieee_mode(precision, rounding, exception_mask):
    gsl = load_gsl_libraries()
    gsl.gsl_ieee_set_mode.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_int]
    gsl.gsl_ieee_set_mode.restype = ctypes.c_int
    return gsl.gsl_ieee_set_mode(precision, rounding, exception_mask)

def main():
    if len(sys.argv) != 4:
        print("Usage: python script.py <precision> <rounding> <exception_mask>")
        sys.exit(1)
    try:
        precision = int(sys.argv[1])
        rounding = int(sys.argv[2])
        exception_mask = int(sys.argv[3])
        result = set_ieee_mode(precision, rounding, exception_mask)
        print(result)
    except ValueError:
        print("All arguments must be integers.")
    except OSError as e:
