class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        self.data = (ctypes.c_double * (self.rows * self.cols))()
        self.matrix = ctypes.pointer(ctypes.pointer(ctypes.Structure()))
        gsl.gsl_matrix_alloc.restype = ctypes.c_void_p
