import ctypes
import sys

class GslRstatQuantileWorkspace:
    def __init__(self, p):
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        self.cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl.gsl_rstat_quantile_alloc.restype = ctypes.c_void_p
        self.gsl.gsl_rstat_quantile_alloc.argtypes = [ctypes.c_double]
        self.workspace = self.gsl.gsl_rstat_quantile_alloc(p)
        if not self.workspace:
            raise MemoryError("Failed to allocate quantile workspace")

    def reset(self):
        self.gsl.gsl_rstat_quantile_reset(self.workspace)

    def add(self, value):
        self.gsl.gsl_rstat_quantile_add.restype = None
        self.gsl.gsl_rstat_quantile_add.argtypes = [ctypes.c_void_p, ctypes.c_double]
        self.gsl.gsl_rstat_quantile_add(self.workspace, value)

    def get(self):
        self.gsl.gsl_rstat_quantile_get.restype = ctypes.c_double
        self.gsl.gsl_rstat_quantile_get.argtypes = [ctypes.c_void_p]
        return self.gsl.gsl_rstat_quantile_get(self.workspace)

    def free(self):
        self.gsl.gsl_rstat_quantile_free(self.workspace)


def compute_quantile(p, values):
    if not (0 <= p <= 1):
        raise ValueError("Quantile p must be between 0 and 1")
    workspace = GslRstatQuantileWorkspace(p)
    try:
        workspace.reset()
        for value in values:
            workspace.add(value)
        return workspace.get()
    finally:
        workspace.free()

if __name__ == '__main__':
    p = float(sys.argv[1])
    values = [float(x) for x in sys.argv[2:]]
    quantile = compute_quantile(p, values)
    print(quantile)
